CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY, name text NOT NULL, nickname text NOT NULL, password text NOT NULL, role text NOT NULL CHECK(role IN ('admin','member')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX users_name ON users(lower(name));
CREATE TABLE sessions(token text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users, expires_at timestamptz NOT NULL);
CREATE TABLE login_attempts(key text PRIMARY KEY, attempts integer NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE workspaces(id uuid PRIMARY KEY, name text NOT NULL, owner_id uuid NOT NULL REFERENCES users, kind text NOT NULL CHECK(kind IN ('personal','team')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE members(workspace_id uuid REFERENCES workspaces, user_id uuid REFERENCES users, PRIMARY KEY(workspace_id,user_id));
CREATE TABLE invites(id uuid PRIMARY KEY, code_hash text NOT NULL UNIQUE, name text NOT NULL, workspace_id uuid REFERENCES workspaces, credits bigint NOT NULL DEFAULT 0 CHECK(credits>=0), enabled boolean NOT NULL DEFAULT true, expires_at timestamptz, uses integer NOT NULL DEFAULT 0);
CREATE TABLE wallets(workspace_id uuid PRIMARY KEY REFERENCES workspaces, balance bigint NOT NULL DEFAULT 0 CHECK(balance>=0), held bigint NOT NULL DEFAULT 0 CHECK(held>=0 AND held<=balance));
CREATE TABLE ledger(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces, job_id uuid, key text NOT NULL UNIQUE, action text NOT NULL, amount bigint NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE plugin_versions(id text NOT NULL, version text NOT NULL, manifest jsonb NOT NULL, endpoint text, PRIMARY KEY(id,version));
CREATE TABLE connections(id uuid PRIMARY KEY, name text NOT NULL, plugin_id text NOT NULL, plugin_version text NOT NULL, config text NOT NULL, revision integer NOT NULL DEFAULT 1, enabled boolean NOT NULL DEFAULT false, concurrency integer NOT NULL DEFAULT 1 CHECK(concurrency BETWEEN 1 AND 100), FOREIGN KEY(plugin_id,plugin_version) REFERENCES plugin_versions);
CREATE TABLE models(id uuid PRIMARY KEY, connection_id uuid NOT NULL REFERENCES connections, provider_model text NOT NULL, label text NOT NULL, kind text NOT NULL, schema jsonb NOT NULL, enabled boolean NOT NULL DEFAULT false, price bigint CHECK(price>0), UNIQUE(connection_id,provider_model));
CREATE TABLE model_permissions(workspace_id uuid REFERENCES workspaces, model_id uuid REFERENCES models, enabled boolean NOT NULL, PRIMARY KEY(workspace_id,model_id));
CREATE TABLE assets(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces, owner_id uuid NOT NULL REFERENCES users, object_key text NOT NULL UNIQUE, mime text NOT NULL, size bigint NOT NULL CHECK(size>=0), state text NOT NULL CHECK(state IN ('uploading','ready')), metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE jobs(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces, owner_id uuid NOT NULL REFERENCES users, model_id uuid NOT NULL REFERENCES models, connection_id uuid NOT NULL REFERENCES connections, plugin_id text NOT NULL, plugin_version text NOT NULL, config_snapshot text NOT NULL, provider_model text NOT NULL, kind text NOT NULL, input jsonb NOT NULL, idempotency_key text NOT NULL, request_hash text NOT NULL, price bigint NOT NULL CHECK(price>0), state text NOT NULL CHECK(state IN ('queued','dispatching','running','finalizing','uncertain','completed','failed','cancelled')), remote_id text, receipt jsonb, error text, lease_token uuid, lease_until timestamptz, cancel_requested boolean NOT NULL DEFAULT false, result jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,workspace_id,idempotency_key));
CREATE INDEX jobs_queue ON jobs(state,created_at);
CREATE INDEX jobs_workspace ON jobs(workspace_id,created_at DESC);
CREATE TABLE job_assets(job_id uuid REFERENCES jobs, asset_id uuid REFERENCES assets, role text NOT NULL, PRIMARY KEY(job_id,asset_id,role));
CREATE TABLE outbox(job_id uuid PRIMARY KEY REFERENCES jobs, available_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz);
CREATE TABLE job_events(id bigserial PRIMARY KEY, job_id uuid NOT NULL REFERENCES jobs, state text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE gpu_pairings(token text PRIMARY KEY, connection_id uuid NOT NULL REFERENCES connections, expires_at timestamptz NOT NULL, claimed boolean NOT NULL DEFAULT false);
CREATE TABLE gpu_nodes(id uuid PRIMARY KEY, connection_id uuid NOT NULL REFERENCES connections, name text NOT NULL, token_hash text NOT NULL UNIQUE, models jsonb NOT NULL, enabled boolean NOT NULL DEFAULT true, last_seen timestamptz NOT NULL DEFAULT now());
CREATE TABLE documents(id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces, owner_id uuid NOT NULL REFERENCES users, kind text NOT NULL CHECK(kind IN ('canvas','pack','chat')), title text NOT NULL, body jsonb NOT NULL, revision integer NOT NULL DEFAULT 1, deleted boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX documents_workspace ON documents(workspace_id,kind,updated_at DESC);
CREATE TABLE document_assets(document_id uuid REFERENCES documents, asset_id uuid REFERENCES assets, PRIMARY KEY(document_id,asset_id));
CREATE TABLE favorites(user_id uuid REFERENCES users, asset_id uuid REFERENCES assets, PRIMARY KEY(user_id,asset_id));
CREATE TABLE audit_events(id bigserial PRIMARY KEY, actor_id uuid REFERENCES users, action text NOT NULL, resource text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE import_records(source text NOT NULL, kind text NOT NULL, legacy_id text NOT NULL, target_id uuid NOT NULL, PRIMARY KEY(source,kind,legacy_id));
